head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf15200";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bndMktactTpCd", fn: function () { return String(String((dma_pageContext.get("bndMktactTpCd") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_datefmt_cal_procsReqDd
 * @description 초기화 — datefmt cal procs Req Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_procsReqDd = function () { $c.date.checkCalendarFormat("cal_procsReqDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_isuexerDd
 * @description 초기화 — datefmt cal isuexer Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_isuexerDd = function () { $c.date.checkCalendarFormat("cal_isuexerDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.getBdchrgInfo($c.util.getComponent('slc_bdchrgTpCd'));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":2
        ,"mmenu":9
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf15200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_isuexerDd();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf15200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15200.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15200.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name ipt_stkRelCorpbndExerPrc_onkeyup
 * @description ipt_stkRelCorpbndExerPrc 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkRelCorpbndExerPrc_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (($c.util.getComponent('txt_stkRelCorpbndExerPrcKor') && $c.util.getComponent('txt_stkRelCorpbndExerPrcKor').setValue) ? $c.util.getComponent('txt_stkRelCorpbndExerPrcKor').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) === null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'stk_rel_corpbnd_exer_prc_kor'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15200.ipt_stkRelCorpbndExerPrc_onkeyup' }); }
};

/**
 * @method
 * @name ipt_exerAmt_onkeyup
 * @description ipt_exerAmt 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_exerAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (($c.util.getComponent('txt_exerAmtKor') && $c.util.getComponent('txt_exerAmtKor').setValue) ? $c.util.getComponent('txt_exerAmtKor').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) === null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'exer_amt_kor'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15200.ipt_exerAmt_onkeyup' }); }
};

/**
 * @method
 * @name slc_bdchrgTpCd_onchange
 * @description slc_bdchrgTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_bdchrgTpCd_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.getBdchrgInfo(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15200.slc_bdchrgTpCd_onchange' }); }
};

/**
 * @method
 * @name btn_fileBrowse_onclick
 * @description btn_fileBrowse 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileBrowse_onclick = function(e){
    try {
        $c.util.onUploadClick($c.util.getComponent('mpd_files'))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15200.btn_fileBrowse_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
