 */
scwin.btn_delRow_onclick = function(e){
    try {
        fn_delRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15200.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name btn_save_onclick
 * @description btn_save 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15200.btn_save_onclick' }); }
};

/**
 * @method
 * @name btn_searchIsuInfoChgList_onclick
 * @description btn_searchIsuInfoChgList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchIsuInfoChgList_onclick = async function(e){
    try {
        await scwin.searchIsuInfoChgList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15200.btn_searchIsuInfoChgList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchIsuInfoChgList
 * @description search Isu Info Chg List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchIsuInfoChgList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchIsuInfoChgList",
        method: "post",
        action: "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList",
        ref: "dma_searchIsuInfoChgListReq",
        target: "dlt_bdchrgTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function () {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: "/company/company.do?method=saveNondivideBw",
        ref: "dma_saveReq",
        target: "dlt_bdchrgTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_GetBdchrgInfo
 * @description Get Bdchrg Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetBdchrgInfo = async function () {
    const sbmOptions = {
        id: "tx_fn_GetBdchrgInfo",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_GetBdchrgInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name CheckReqInfo_Cellphone
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.CheckReqInfo_Cellphone = async function (fm) { try { const v = (fm && fm.getValue) ? fm.getValue() : (fm && fm.value !== null ? fm.value : null); if (v === null || String(v) === '') { return true; } if (!$c.str.isMobilePhone(String(v))) { await $c.win.alert('휴대전화번호 형식을 확인해 주세요.'); return false; } return true; } catch (_e) { return true; } };

/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name searchIsuInfoChgList
 * @description search Isu Info Chg List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchIsuInfoChgList = async function () {
    const fm = (document.SendForm || { elements: [] });
    fm.action = '/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList';
    fm.target = '_self';
    await scwin.tx_fn_searchIsuInfoChgList();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent("dma_searchIsuInfoChgListReq").set("applIsuNm", $c.util.getComponent('ipt_divUnqIsuNm').getValue());
    $c.util.getComponent("dma_searchIsuInfoChgListReq").set("applIsuEngNm", $c.util.getComponent('ipt_divUnqIsuEngNm').getValue());
    fm.action = '/company/company.do?method=saveNondivideBw';
    await scwin.tx_fn_save();
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const fm = (document.SendForm || { elements: [] });
    const _mktact_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("bndMktactTpCd");
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("isurCd");
    if (!applTmCheck(_mktact_cd, _now_time, _isur_cd)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) === 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_divUnqIsuNm').getValue()) === 0) {
                await $c.win.alert("분리종목명을 입력하십시오.");
                $c.util.getComponent("ipt_divUnqIsuNm").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('ipt_divUnqIsuEngNm').getValue()) === 0) {
                    await $c.win.alert("분리종목영문명을 입력하십시오.");
                    $c.util.getComponent("ipt_divUnqIsuEngNm").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('ipt_stkRelCorpbndExerPrc').getValue()) === 0) {
                        await $c.win.alert("행사가격을 입력하십시오.");
                        $c.util.getComponent("ipt_stkRelCorpbndExerPrc").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('ipt_exerShrs').getValue()) === 0) {
                            await $c.win.alert("주식수를 입력하십시오.");
                            $c.util.getComponent("ipt_exerShrs").focus();
                            return false;
                        } else {
                            if ($c.str.getByteLength($c.util.getComponent('ipt_exerAmt').getValue()) === 0) {
                                await $c.win.alert("최초행사금액을 입력하십시오.");
                                $c.util.getComponent("ipt_exerAmt").focus();
                                return false;
                            } else {
                                if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                                    return false;
                                } else {
                                    if ($c.str.getByteLength($c.util.getComponent('slc_bdchrgTpCd').getValue()) === 0) {
                                        return false;
                                    } else {
                                        if (!await scwin.CheckReqInfo_Cellphone(fm)) {
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent("cal_procsReqDd").setValue("");
    $c.util.getComponent("ipt_divUnqIsuNm").setValue("");
    $c.util.getComponent("ipt_divUnqIsuEngNm").setValue("");
    $c.util.getComponent("ipt_exerAmt").setValue("");
    $c.util.getComponent("ipt_exerShrs").setValue("");
    $c.util.getComponent("ipt_stkRelCorpbndExerPrc").setValue("");
    $c.util.getComponent("cal_isuexerDd").setValue("");
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo !== null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctTelNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_apctTelNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_apctTelNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setCellphoneNo
 * @description set Cellphone No 처리
 * @param {*} pCellphoneNo pCellphoneNo
 * @returns {void}
 * @hidden N
 */
scwin.setCellphoneNo = function (pCellphoneNo) {
    if (pCellphoneNo !== null && pCellphoneNo !== '') {
        const pCellphoneNoArr = pCellphoneNo.split('-');
        if (pCellphoneNoArr.length === 3) {
            $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(pCellphoneNoArr[0]);
            $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(pCellphoneNoArr[1]);
            $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(pCellphoneNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setEmail
 * @description set Email 처리
 * @param {*} pEmail pEmail
 * @returns {void}
 * @hidden N
 */
scwin.setEmail = function (pEmail) {
    if (pEmail !== null && pEmail !== '') {
        const pEmailArr = pEmail.split('@');
        if (pEmailArr.length === 2) {
            $c.util.getComponent('ipt_encrypApctEmail1').setValue(pEmailArr[0]);
            $c.util.getComponent('ipt_encrypApctEmail2').setValue(pEmailArr[1]);
        } else {

        }
    }
};

/**
 * @method
 * @name setFaxNo
 * @description set Fax No 처리
 * @param {*} pFaxNo pFaxNo
 * @returns {void}
 * @hidden N
 */
scwin.setFaxNo = function (pFaxNo) {
    if (pFaxNo !== null && pFaxNo !== '') {
        const pFaxNoArr = pFaxNo.split('-');
        if (pFaxNoArr.length === 3) {
            if (pFaxNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctFaxNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctFaxNo1').setValue(pFaxNoArr[0]);
            }
            $c.util.getComponent('ipt_apctFaxNo2').setValue(pFaxNoArr[1]);
            $c.util.getComponent('ipt_apctFaxNo3').setValue(pFaxNoArr[2]);
        } else {

        }
    }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(isuinfochgsearch vs company) — 어느 쪽인지 정할 근거가 없다

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name getBdchrgInfoDone
 * @description get Bdchrg Info Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getBdchrgInfoDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_chrgId').setValue(result.chrg_id);
    $c.util.getComponent('ipt_apctNm').setValue(result.chrg_nm);
    $c.util.getComponent('ipt_jobposNm').setValue(result.jobpos_nm);
    $c.util.getComponent('ipt_belngInstNm').setValue(result.belng_inst_nm);
    $c.util.getComponent('ipt_belngDepNm').setValue(result.belng_dep_nm);
    scwin.setTelNo(result.tel_no);
    scwin.setCellphoneNo(result.cellphone_no);
    scwin.setEmail(result.email);
    scwin.setFaxNo(result.fax_no);
};

/**
 * @method
 * @name getBdchrgInfo
 * @description get Bdchrg Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getBdchrgInfo = async function () {
    const r = await scwin.tx_fn_GetBdchrgInfo();
    try {
        scwin.getBdchrgInfoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body !== null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf15200.fn_GetBdchrgInfo' });
    }
    return r;
};
